--region handler

function JapaneseStoryChapterDialog:ChapterNodeOnClickHandler(index)
    local data = JapaneseStoryMgr:GetMainQuestMap()[index]
    if not data then return end

    if checkInt(data.unlockCountdown) > 0 then
        local text = string.format(localize("距离开放：_num_", {_num_ =CfUtils.GetTimeHMS10(checkInt(data.unlockCountdown + JapaneseStoryMgr:GetEnterTimestamp() - GameUtils.GetServerTime()))}))
        GameUtils.Toast(text)
        return
    elseif checkInt(data.status) == 0 then
        GameUtils.Toast(localize('通关上一个章节后解锁'))
        return
    end
    
    CfUtils.DialogOpen(Constants.UITypeIds.ActivityJapaneseStoryChapterDialog, {chapterData = data, chapterIdx = index}, {UIArgs(Constants.UITypeIds.ActivityJapaneseStoryLevelMain)})
end
--endregion handler

--region private
---刷新章节节点
function JapaneseStoryChapterDialog:RefreshChapterNode()
    local data = JapaneseStoryMgr:GetMainQuestMap()
    for i, v in ipairs(data) do
        local go = self.EnterRoot:Find("Cell"..i)
        if isNull(go) then
            go = CfUtils.InstantiateGo(self.Cell, self.EnterRoot)
            go.name = "Cell" .. i
        end

        local env = CfUtils.GetLuaScr(go, JapaneseStoryConstants.ScrPath.JapaneseStoryChapterNode)
        if isNotNull(env) then
            env:RefreshNode(v, i, Bind(self, self.ChapterNodeOnClickHandler))
        end
    end
end

---刷新进度条
function JapaneseStoryChapterDialog:RefreshProgressBar()
    local chapterId, _ = JapaneseStoryMgr:GetNewQuest()
    local index = self:GetChapterIndex(chapterId)
    if index == 1 then
        self.Slider.value = 0.1
    elseif index == 2 then
        self.Slider.value = 0.5
    elseif index == 3 then
        self.Slider.value = 1
    end

    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local gender = checkInt(comp.playerDojo.gender)
    if gender == Constants.PLAYER_GENDER.FEMALE then
        CfUtils.SetUISwitchImage(self.ImgHead, 2)
    elseif gender == Constants.PLAYER_GENDER.MALE then
        CfUtils.SetUISwitchImage(self.ImgHead, 1)
    end
end

---获取章节位置
---@param chapterId integer 
function JapaneseStoryChapterDialog:GetChapterIndex(chapterId)
    local data = JapaneseStoryMgr:GetMainQuestMap()
    for i, v in ipairs(data) do
        if checkInt(v.questId) == checkInt(chapterId) then
            return i
        end
    end
end
--endregion private

return JapaneseStoryChapterDialog